func candidatesFixture(t *testing.T, refOnUpstream, refOnOrigin bool) (workDir string, ref plumbing.ReferenceName, upstreamHash, originHash string) {
	t.Helper()
	testutil.IsolateGitConfigEnv(t)

	upstreamBare := t.TempDir()
