func TestSyncFromPolicyElectedTargetAdvancesLocalRef(t *testing.T) {
	bareDir, remoteHash := initPolicyBare(t, checkpointpolicy.DefaultPolicy())

	localDir, localRepo := initPolicyRepoWithDir(t)
