// origin's tracking ref — the legacy read tier never feeds local-ref writes.
func TestEnsurePrimaryRef_StaleOriginTrackingNeverSeedsWhenElectedElsewhere(t *testing.T) {
	tmpDir := initRemoteElectionRepo(t)
