	cmd := exec.CommandContext(ctx, "git", cloneArgs...)
	cmd.Env = testutil.GitIsolatedEnv()
	if output, err := cmd.CombinedOutput(); err != nil {
		env.T.Fatalf("failed to clone from %s: %v\n%s", bareDir, err, output)
	}

