+
+// TestCheckpointRefsDiscovery_CrossMachineElectedRemote: git-refs only — a
+// fresh clone with zero local checkpoint state discovers a refs-native
+// checkpoint that exists only on its elected non-origin remote, then hydrates
+// it on read. This closes the default-setup gap scoped out in #1771 without
+// letting discovery advertise a checkpoint that the read path cannot fetch.
+func TestCheckpointRefsDiscovery_CrossMachineElectedRemote(t *testing.T) {
+	t.Parallel()
+
+	env := NewFeatureBranchEnv(t)
+	env.CheckpointStore = StoreGitRefs
+
