+			"checkpoint_push_remote": "upstream",
+		},
+	})
+
+	checkpointID := createCheckpointedCommit(t, env, "Add machine module", "machine.go", "package machine", "Add machine module")
+	env.GitPush("origin", "HEAD")
+	env.RunPrePush("upstream")
+	if !env.CheckpointExistsOnRemote(bareUpstream, checkpointID) {
+		t.Fatalf("checkpoint %s should be on upstream", checkpointID)
+	}
+	if env.CheckpointExistsOnRemote(bareOrigin, checkpointID) {
+		t.Fatalf("fixture: checkpoint %s must exist only on upstream", checkpointID)
+	}
+
+	// Machine B: a fresh clone with no local checkpoint refs and no dedicated
+	// checkpoint_remote. It elects the same non-origin remote that holds the
+	// checkpoint, while origin contains only the source branch.
+	cloneEnv := env.CloneFrom(bareOrigin)
